import { useEffect, useState } from "react";
import axios from "axios";
import Login from "./components/Login";

const API_URL = "http://localhost:5000";

function App() {
  // =======================
  // STATE
  // =======================
  const [candidates, setCandidates] = useState([]);
  const [auth, setAuth] = useState({
    token: localStorage.getItem("token"),
    role: localStorage.getItem("role"),
  });

  const [loginForm, setLoginForm] = useState({
    email: "",
    password: "",
  });

  const [candidateForm, setCandidateForm] = useState({
    name: "",
    position: "",
    description: "",
  });

  const [message, setMessage] = useState("");

  // =======================
  // API CALLS
  // =======================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch (err) {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
  }, []);

  const handleLogin = async () => {
    try {
      const res = await axios.post(`${API_URL}/api/auth/login`, loginForm);

      localStorage.setItem("token", res.data.token);
      localStorage.setItem("role", res.data.role);

      setAuth({
        token: res.data.token,
        role: res.data.role,
      });

      setMessage("Login successful.");
    } catch (err) {
      setMessage("Invalid email or password.");
    }
  };

  const handleVote = async (candidateId) => {
    try {
      await axios.post(
        `${API_URL}/api/vote/${candidateId}`,
        {},
        {
          headers: {
            Authorization: `Bearer ${auth.token}`,
          },
        }
      );

      setMessage("Vote submitted successfully.");
      fetchCandidates();
    } catch (err) {
      setMessage("You already voted or an error occurred.");
    }
  };

  const handleAddCandidate = async () => {
    try {
      await axios.post(`${API_URL}/api/candidates`, candidateForm, {
        headers: {
          Authorization: `Bearer ${auth.token}`,
        },
      });

      setMessage("Candidate added successfully.");
      setCandidateForm({ name: "", position: "", description: "" });
      fetchCandidates();
    } catch (err) {
      setMessage("Failed to add candidate.");
    }
  };

  // =======================
  // UI
  // =======================
  return (
    <div style={{ maxWidth: 700, margin: "auto", padding: 20 }}>
      <h1 style={{ textAlign: "center" }}>Online Voting System</h1>

      {message && <p style={{ color: "green" }}>{message}</p>}

      {/* LOGIN */}
      {!auth.token && (
        <section>
          <h2>Login</h2>
          <input
            type="email"
            placeholder="Email"
            value={loginForm.email}
            onChange={(e) =>
              setLoginForm({ ...loginForm, email: e.target.value })
            }
          />
          <br />
          <input
            type="password"
            placeholder="Password"
            value={loginForm.password}
            onChange={(e) =>
              setLoginForm({ ...loginForm, password: e.target.value })
            }
          />
          <br />
          <button onClick={handleLogin}>Login</button>
        </section>
      )}

      {/* ADMIN PANEL */}
      {auth.role === "admin" && (
        <section>
          <h2>Admin Panel – Add Candidate</h2>
          <input
            placeholder="Candidate Name"
            value={candidateForm.name}
            onChange={(e) =>
              setCandidateForm({ ...candidateForm, name: e.target.value })
            }
          />
          <br />
          <input
            placeholder="Position"
            value={candidateForm.position}
            onChange={(e) =>
              setCandidateForm({ ...candidateForm, position: e.target.value })
            }
          />
          <br />
          <textarea
            placeholder="Description"
            value={candidateForm.description}
            onChange={(e) =>
              setCandidateForm({
                ...candidateForm,
                description: e.target.value,
              })
            }
          />
          <br />
          <button onClick={handleAddCandidate}>Add Candidate</button>
        </section>
      )}

      {/* CANDIDATES */}
      <section>
        <h2>Candidates</h2>
        {candidates.map((candidate) => (
          <div
            key={candidate._id}
            style={{
              border: "1px solid #ccc",
              padding: 15,
              marginBottom: 10,
              borderRadius: 5,
            }}
          >
            <h3>{candidate.name}</h3>
            <p><strong>Position:</strong> {candidate.position}</p>
            <p>{candidate.description}</p>
            <p><strong>Votes:</strong> {candidate.votes}</p>

            {auth.token && auth.role === "user" && (
              <button onClick={() => handleVote(candidate._id)}>
                Vote
              </button>
            )}
          </div>
        ))}
      </section>
    </div>
  );
}

export default App;
